import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import * as nodemailer from 'nodemailer';

@Injectable()
export class EmailService {
  private readonly logger = new Logger(EmailService.name);
  private transporter: nodemailer.Transporter;

  constructor(private config: ConfigService) {
    this.transporter = nodemailer.createTransport({
      host: config.get('MAIL_HOST', 'mail.conectaai.cl'),
      port: parseInt(config.get('MAIL_PORT', '587')),
      secure: config.get('MAIL_SECURE', 'false') === 'true',
      auth: {
        user: config.get('MAIL_USER'),
        pass: config.get('MAIL_PASS'),
      },
      tls: { rejectUnauthorized: false },
    });
  }

  private get from() {
    const name = this.config.get('MAIL_FROM_NAME', 'CmrArena ERP');
    const addr = this.config.get('MAIL_FROM', 'noreply@conectaai.cl');
    return `"${name}" <${addr}>`;
  }

  async sendQuotationEmail(params: {
    to: string;
    clientName: string;
    quotationNumber: number;
    total: number;
    companyName: string;
    validUntil?: Date;
  }) {
    const subject = `Cotización N°${String(params.quotationNumber).padStart(4, '0')} - ${params.companyName}`;
    const html = `
<!DOCTYPE html>
<html lang="es">
<head><meta charset="UTF-8"><style>
body { font-family: Arial, sans-serif; color: #333; max-width: 600px; margin: 0 auto; }
.header { background: #0f172a; color: white; padding: 20px; text-align: center; }
.content { padding: 20px; }
.total { background: #f1f5f9; padding: 15px; border-radius: 8px; text-align: center; margin: 20px 0; }
.total-amount { font-size: 28px; font-weight: bold; color: #0f172a; }
.btn { display: inline-block; background: #0f172a; color: white; padding: 12px 24px;
       text-decoration: none; border-radius: 6px; margin-top: 10px; }
.footer { font-size: 12px; color: #666; text-align: center; padding: 20px; }
</style></head>
<body>
<div class="header"><h2>${params.companyName}</h2></div>
<div class="content">
  <p>Estimado/a <strong>${params.clientName}</strong>,</p>
  <p>Le enviamos su cotización <strong>N°${String(params.quotationNumber).padStart(4, '0')}</strong>.</p>
  <div class="total">
    <div>Monto Total</div>
    <div class="total-amount">$${Math.round(params.total).toLocaleString('es-CL')}</div>
    ${params.validUntil ? `<div style="font-size:12px;margin-top:5px;">Válida hasta: ${new Date(params.validUntil).toLocaleDateString('es-CL')}</div>` : ''}
  </div>
  <p>Para aprobar esta cotización o solicitar modificaciones, por favor contáctenos.</p>
</div>
<div class="footer">Este email fue enviado por ${params.companyName} a través de CmrArena ERP</div>
</body></html>`;

    await this.send({ to: params.to, subject, html });
  }

  async sendWelcomeEmail(params: { to: string; firstName: string; tenantName: string; tempPassword: string }) {
    const subject = `Bienvenido a ${params.tenantName} - CmrArena ERP`;
    const html = `
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><style>
body { font-family: Arial, sans-serif; color: #333; max-width: 600px; margin: 0 auto; }
.header { background: #0f172a; color: white; padding: 20px; text-align: center; }
.content { padding: 20px; }
.credentials { background: #f1f5f9; padding: 15px; border-radius: 8px; font-family: monospace; }
</style></head><body>
<div class="header"><h2>CmrArena ERP</h2></div>
<div class="content">
  <p>Hola <strong>${params.firstName}</strong>, ¡bienvenido/a a <strong>${params.tenantName}</strong>!</p>
  <p>Tu cuenta ha sido creada. Tus credenciales de acceso son:</p>
  <div class="credentials">
    <p>Usuario: <strong>${params.to}</strong></p>
    <p>Contraseña temporal: <strong>${params.tempPassword}</strong></p>
  </div>
  <p style="color:#dc2626"><strong>Importante:</strong> Cambia tu contraseña en el primer inicio de sesión.</p>
</div></body></html>`;

    await this.send({ to: params.to, subject, html });
  }

  async sendLowStockAlert(params: { to: string; products: Array<{ name: string; stock: number; minStock: number }> }) {
    const subject = `Alerta: Productos con stock crítico`;
    const rows = params.products.map(
      (p) => `<tr><td>${p.name}</td><td style="color:red">${p.stock}</td><td>${p.minStock}</td></tr>`,
    ).join('');
    const html = `
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"></head><body style="font-family:Arial,sans-serif">
<h2 style="color:#dc2626">Alerta de Stock Crítico</h2>
<table border="1" cellpadding="8" cellspacing="0" style="width:100%">
  <tr style="background:#f1f5f9"><th>Producto</th><th>Stock Actual</th><th>Stock Mínimo</th></tr>
  ${rows}
</table>
<p>Ingresa al sistema para realizar ajustes de inventario.</p>
</body></html>`;

    await this.send({ to: params.to, subject, html });
  }


  async sendPasswordResetEmail(params: { to: string; firstName: string; resetUrl: string }) {
    const subject = "Recuperación de contraseña — CmrArena ERP";
    const html = `
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><style>
body { font-family: Arial, sans-serif; color: #333; max-width: 600px; margin: 0 auto; }
.header { background: #0f172a; color: white; padding: 20px; text-align: center; }
.content { padding: 24px; }
.btn { display: inline-block; background: #7c3aed; color: white; padding: 12px 28px;
       text-decoration: none; border-radius: 8px; font-weight: 600; margin: 16px 0; }
.note { color: #64748b; font-size: 13px; margin-top: 16px; }
</style></head><body>
<div class="header"><h2>CmrArena ERP</h2></div>
<div class="content">
  <p>Hola <strong>${params.firstName}</strong>,</p>
  <p>Recibimos una solicitud para restablecer la contraseña de tu cuenta.</p>
  <p><a href="${params.resetUrl}" class="btn">Restablecer contraseña</a></p>
  <p class="note">Este enlace expira en 1 hora. Si no solicitaste este cambio, ignora este correo.</p>
</div></body></html>`;

    // Use MAILSAAS REST API (SMTP pass may be empty)
    const apiKey = this.config.get("MAILSAAS_API_KEY");
    const apiUrl = this.config.get("MAILSAAS_URL", "https://mail.conectaai.cl");
    if (apiKey) {
      try {
        const res = await fetch(`${apiUrl}/api/send`, {
          method: "POST",
          headers: { "Content-Type": "application/json", "Authorization": `Bearer ${apiKey}` },
          body: JSON.stringify({ to: params.to, subject, html, from: this.from }),
        });
        if (!res.ok) throw new Error(`MailSaaS error: ${res.status}`);
        this.logger.log(`Password reset email sent via MailSaaS to ${params.to}`);
        return;
      } catch (err) {
        this.logger.warn(`MailSaaS failed, trying SMTP: ${err.message}`);
      }
    }
    await this.send({ to: params.to, subject, html });
  }


  async sendDeliveryEmail(params: {
    to: string;
    clientName: string;
    title: string;
    status: string;
    services: Array<{ type: string; label: string; icon?: string; fields: Array<{ key: string; label: string; value: string; secret?: boolean }> }>;
    notes?: string;
    tenant?: any;
  }) {
    const isActive = params.status === 'ACTIVO';
    const isSuspended = params.status === 'INACTIVO';
    const logoSrc = "data:image/png;base64,";

    const statusBanner = isSuspended
      ? `<div style="background:#fee2e2;border-left:4px solid #dc2626;padding:14px 20px;margin:20px 0;border-radius:0 8px 8px 0"><b style="color:#dc2626">⚠ Acceso suspendido</b><br><span style="color:#7f1d1d;font-size:13px">Su acceso a los servicios ha sido suspendido temporalmente. Para reactivarlo, regularice su pago y contáctenos.</span></div>`
      : '';

    const icons: Record<string, string> = {
      website:'🌐', hosting:'🖥', domain:'🔗', whatsapp_bot:'💬',
      automation:'⚙️', credentials:'🔑', custom:'📦',
    };

    const servicesHtml = (params.services || []).map(svc => {
      const icon = svc.icon || icons[svc.type] || '📦';
      const rows = svc.fields.map(f => {
        const val = isSuspended && f.secret
          ? `<span style="font-family:monospace;background:#f1f5f9;padding:3px 10px;border-radius:4px;color:#94a3b8;letter-spacing:4px">••••••••</span>`
          : `<span style="font-family:monospace;background:#f0fdf4;padding:3px 10px;border-radius:4px;color:#166534;font-weight:600">${f.value}</span>`;
        return `<tr><td style="padding:8px 14px;color:#64748b;font-size:13px;width:38%;border-bottom:1px solid #f1f5f9">${f.label}</td><td style="padding:8px 14px;font-size:13px;border-bottom:1px solid #f1f5f9">${val}</td></tr>`;
      }).join('');
      return `<div style="margin-bottom:18px;border:1px solid #e2e8f0;border-radius:12px;overflow:hidden">
        <div style="background:#f8fafc;padding:13px 18px;border-bottom:1px solid #e2e8f0">
          <span style="font-size:18px;margin-right:8px">${icon}</span>
          <span style="font-weight:700;color:#1e293b;font-size:14px">${svc.label}</span>
        </div>
        <table style="width:100%;border-collapse:collapse">${rows}</table>
      </div>`;
    }).join('');

    const subject = isActive
      ? `✅ Tu proyecto está listo — ${params.title}`
      : isSuspended
      ? `⚠ Acceso suspendido — ${params.title}`
      : `📦 Información de tu proyecto — ${params.title}`;

    const headerMsg = isActive
      ? `<p style="color:#166534;background:#f0fdf4;padding:12px 18px;border-radius:8px;font-weight:600;margin:16px 0">✅ Tu proyecto <strong>${params.title}</strong> está activo y listo para usar.</p>`
      : isSuspended
      ? `<p style="color:#991b1b;background:#fef2f2;padding:12px 18px;border-radius:8px;font-weight:600;margin:16px 0">⚠ El acceso a <strong>${params.title}</strong> ha sido suspendido temporalmente.</p>`
      : `<p style="color:#1e293b;margin:16px 0">A continuación encontrás la información de tu proyecto <strong>${params.title}</strong>.</p>`;

    const notes = params.notes
      ? `<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:14px 18px;margin-top:8px"><b style="color:#92400e">📝 Notas:</b><p style="color:#78350f;margin:6px 0 0;font-size:14px">${params.notes}</p></div>`
      : '';

    const html = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:0;background:#f1f5f9;font-family:Arial,sans-serif">
<div style="max-width:620px;margin:32px auto;background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,.08)">
  <div style="background:linear-gradient(135deg,#1d4ed8 0%,#1e40af 100%);padding:32px;text-align:center">
    <img src="${logoSrc}" alt="ConectaAI" style="height:58px;object-fit:contain;margin-bottom:10px"><br>
    <div style="color:rgba(255,255,255,.75);font-size:12px;letter-spacing:1.5px;text-transform:uppercase">Entrega de Proyecto Digital</div>
  </div>
  <div style="padding:32px">
    <p style="font-size:16px;color:#1e293b;margin-bottom:4px">Hola, <strong>${params.clientName}</strong></p>
    ${headerMsg}
    ${statusBanner}
    ${servicesHtml}
    ${notes}
  </div>
  <div style="background:#f8fafc;padding:20px 32px;text-align:center;border-top:1px solid #e2e8f0">
    <div style="font-size:12px;color:#94a3b8">Enviado por <strong>ConectaAI</strong> · admin@conectaai.cl · conectaai.cl</div>
    <div style="font-size:11px;color:#cbd5e1;margin-top:4px">Este correo contiene información confidencial. No lo reenvíes a terceros.</div>
  </div>
</div>
</body></html>`;

    await this.send({ to: params.to, subject, html });
  }

  private async send(options: { to: string; subject: string; html: string; attachments?: any[] }) {
    try {
      const info = await this.transporter.sendMail({
        from: this.from,
        ...options,
      });
      this.logger.log(`Email enviado: ${info.messageId} → ${options.to}`);
      return info;
    } catch (err) {
      this.logger.error(`Error enviando email a ${options.to}: ${err.message}`);
      throw err;
    }
  }
}
